'use strict';
// One card renderer for the editor, gallery and customer balance.
const studioTemplates=[
 {id:'car',name:'صابونة',category:'مغسلة سيارات',logo:'/sabonh-logo.png',icon:'car',color:'#063b45',accent:'#72f4df',target:5,reward:'خصم على الغسيل',layout:'foam',program:{type:'discount',discountType:'percent',discountValue:20}},
 {id:'coffee',name:'لاتيه',category:'كافيه',logo:'/latte-logo.jpg',icon:'coffee',color:'#302922',accent:'#dfb785',target:5,reward:'قهوة مجانية',layout:'glass',program:{type:'visits'}},
 {id:'salon',name:'العنوان للحلاقة',category:'حلاق',logo:'/address-logo.webp',icon:'scissors',color:'#171b23',accent:'#dfbf79',target:5,reward:'جلسة عناية',layout:'atelier',program:{type:'points',pointsPerVisit:10,pointsCost:50}}
].map(c=>({...c,pattern:false,terms:'تحدد شروط المكافأة والخدمات المؤهلة لدى النشاط.',stampX:50,stampY:60,stampSize:38,backgroundMode:'soft',hideIdentity:false,stampEmptyImage:'',stampImage:'',background:''}));
for(const c of studioTemplates){const t=templates.find(t=>t.id===c.id);if(t)Object.assign(t,c);}
const standardCard=cardHTML;
function cupArt(used){return `<svg class="cup-art" viewBox="0 0 48 54" aria-hidden="true"><path d="M34 18h5c8 0 8 14 0 14h-5" fill="none" stroke="currentColor" stroke-width="3"/><path d="M8 16h27l-2 25c-.4 5-21 5-22 0z" fill="${used?'#ffffff09':'currentColor'}" fill-opacity="${used?1:.22}" stroke="currentColor" stroke-width="1.8"/><ellipse cx="21.5" cy="16" rx="13.5" ry="4" fill="${used?'#ffffff08':'#b58356'}" stroke="currentColor" stroke-width="1.8"/>${used?'':'<path d="M18 14c4-4 8 3 11-1" fill="none" stroke="#f8e5ce" stroke-width="1.2"/>'}<path d="M6 48h32" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>${used?'<path d="m18 30 4 4 7-8" fill="none" stroke="currentColor" stroke-width="2"/>':'<path d="M17 3q-4 4 0 7M26 2q-4 4 0 7" fill="none" stroke="currentColor" stroke-width="1.2"/>'}</svg>`;}
cardHTML=function(c,m=null,full=false){
 if(!['glass','foam','atelier'].includes(c.layout))c={...c,layout:c.icon==='car'?'foam':c.icon==='scissors'?'atelier':'glass'};
 const p=Loyalty.program(c),member=m||{stamps:2,points:20,rewards:0,id:'RJ-PREVIEW01',name:'معاينة البطاقة'},balance=p.type==='points'?(member.points||0):(member.stamps||0),goal=p.type==='points'?p.pointsCost:c.target,ready=Loyalty.available(member,c),count=p.type==='points'?c.target:c.target,completed=ready?count:p.type==='points'?Math.floor(Math.min(1,balance/goal)*count):balance;
 const n=(v,d,min,max)=>Math.max(min,Math.min(max,Number.isFinite(Number(v))?Number(v):d));
 const positions=studioPositions(c);
 const art=c.backgroundMode==='artwork',hide=c.hideIdentity===true;
 return `<div class="loyalty-card studio-card studio-${c.layout} ${art?'full-artwork':''} ${c.glassShine===true?'studio-shine':''} ${full?'studio-full':''} ${c.itemCoordinateSpace==='card'?'studio-card-space':''}" style="--card:${esc(c.color)};--accent:${esc(c.accent)};--stamp-x:${n(c.stampX,50,0,100)}%;--stamp-y:${n(c.stampY,60,0,100)}%;--stamp-size:${n(c.stampSize,38,22,160)}px">
 ${c.background?`<img class="studio-background" src="${esc(c.background)}" alt="">`:''}<div class="studio-grain" aria-hidden="true"></div><div class="studio-orb" aria-hidden="true"></div>
 ${hide?'':`<div class="studio-identity">${c.logo?`<img class="studio-logo" src="${esc(c.logo)}" alt="شعار ${esc(c.name)}">`:icon(c.icon)}<div><strong>${esc(c.name)}</strong><small>${esc(c.category)}</small></div></div>`}
 <div class="studio-heading"><span>${p.type==='points'?'MEMBERS CLUB':p.type==='discount'?'A LITTLE EXTRA':'YOUR DAILY RITUAL'}</span><h3>${p.type==='points'?'كل زيارة، قيمة.':p.type==='discount'?'لمعة تستاهل أكثر.':'لحظتك، تستاهل أكثر.'}</h3><p>${p.type==='points'?'بطاقة النقاط':p.type==='discount'?'بطاقة الخصومات':'بطاقة الزيارات'}</p></div>
 <div class="studio-balance"><b>${fmt(balance)}</b><span>${p.type==='points'?'نقطة':'زيارة'} <small> / ${fmt(goal)}</small></span></div>
 <div class="studio-stamps studio-free" aria-label="${fmt(balance)} من ${fmt(goal)}"><div class="studio-stamp-grid">${Array.from({length:count},(_,i)=>{const used=i<completed,src=used?c.stampImage:c.stampEmptyImage;return `<span class="studio-stamp ${used?'earned':''}" data-item="${i}" style="left:${positions[i].x}%;top:${positions[i].y}%;--stamp-size:${positions[i].size}px" title="${used?'زيارة مكتملة':'زيارة قادمة'}">${src?`<img src="${esc(src)}" alt="${used?'بعد الزيارة':'قبل الزيارة'}">`:c.icon==='coffee'?cupArt(used):icon(used?'check':c.icon)}</span>`;}).join('')}</div></div>
 <div class="studio-bottom"><div class="studio-reward">${icon('gift')}<span>${ready?`${fmt(ready)} مكافأة جاهزة`:esc(Loyalty.label(c))}<small>${ready?'شكرًا لرجعتك':p.type==='points'?`${fmt(Math.max(0,goal-balance))} نقطة للمكافأة`:`${fmt(Math.max(0,goal-balance))} زيارات للمكافأة`}</small></span></div>${full?`<div class="studio-code ${p.barcodeFormat==='code128'?'wide-code':''}">${codeHTML(c,member)}</div><div class="studio-member">${esc(member.name)} · ${esc(member.id)}</div>${m?'<button class="card-code-expand" data-action="expand-code">عرض الرمز كاملًا</button>':''}`:'<div class="studio-footnote">LOYALTY, MADE PERSONAL <span>✦</span></div>'}</div></div>`;
};
const studioHome=homeHTML;
homeHTML=function(){const box=document.createElement('div');box.innerHTML=studioHome();const ring=box.querySelector('.card-ring');if(ring)ring.innerHTML=studioTemplates.map((c,i)=>`<div class="showcase-item showcase-${i}"><div id="demo-card-${c.id}">${cardHTML(c)}</div><button class="demo-visit" data-action="studio-demo" data-template="${c.id}">جرّب ${c.program.type==='points'?'إضافة نقاط':'زيارة'} ↗</button><p>${esc(c.name)} · ${['خصومات','زيارات','نقاط'][i]}</p></div>`).join('');const h=box.querySelector('.gallery-heading');if(h)h.innerHTML='<span>01 / استوديو البطاقات</span><h2>هوية مختلفة. تجربة تتغيّر.</h2><p>ثلاث تصاميم مقترحة للمعاينة. جرّب زيارة وشاهد البطاقة تتفاعل.</p>';const hint=box.querySelector('.gallery-hint');if(hint)hint.textContent='نماذج تصميم؛ المكافآت المعروضة أمثلة قابلة للتعديل.';return box.innerHTML;};
const studioDesign=designHTML;
designHTML=function(){const box=document.createElement('div');box.innerHTML=studioDesign();draft.layout||=draft.icon==='car'?'foam':draft.icon==='scissors'?'atelier':'glass';const section=box.querySelector('.editor-section:nth-child(2)');if(section){section.insertAdjacentHTML('afterbegin',`<div class="studio-tools"><span class="studio-eyebrow">DESIGN STUDIO</span><h2>صمّمها بطريقتك</h2><p>ابدأ بأسلوب جاهز، ثم خصّص الخلفية وعناصر الرصيد.</p><div class="studio-presets">${[['glass','زجاجي','قهوة ولمسات دافئة'],['foam','مائي','تدرّجات وانتعاش'],['atelier','فاخر','ألوان عميقة ولمعان']].map(([id,name,sub])=>`<button class="studio-preset ${draft.layout===id?'selected':''}" data-action="studio-style" data-style="${id}"><span class="preset-swatch ${id}"></span><strong>${name}</strong><small>${sub}</small></button>`).join('')}</div></div>`);section.insertAdjacentHTML('beforeend',`<div class="studio-controls"><label class="studio-toggle"><input type="checkbox" data-studio="glassShine" ${draft.glassShine===true?'checked':''}> مظهر زجاجي مع لمعة متحركة</label><p class="line-meta">اللمعة تتحرك في بطاقة الموقع. عرض المحفظة يعتمد على إمكانات مزود Wallet.</p><h3>العنصر قبل الزيارة وبعدها</h3><p class="sub">للكوب: ارفع صورة ممتلئة قبل الزيارة وصورة فارغة بعدها. يتبدّل تلقائيًا مع رصيد العميل.</p>${mediaField('stampEmptyImage','stamp-empty-file','صورة قبل الزيارة')}<p class="line-meta">«صورة ختم مخصصة» أعلاه هي الصورة بعد الزيارة.</p><h3>كل عنصر في مكانه</h3><p class="sub">اسحب أي كوب أو رمز داخل المعاينة، أو اختره وعدّل مكانه وحجمه هنا. الخيارات تعمل مع الزيارات والخصومات والنقاط.</p><label class="field"><span>العنصر</span><select id="studio-item-select">${Array.from({length:draft.target},(_,i)=>`<option value="${i}">العنصر ${fmt(i+1)}</option>`).join('')}</select></label>${[['x','يمين ويسار',0,100],['y','فوق وتحت',0,100],['size','حجم هذا العنصر',22,160]].map(([key,label,min,max])=>`<label class="field"><span>${label}</span><input type="range" data-item-control="${key}" aria-label="${label}" min="${min}" max="${max}" value="${studioPositions(draft)[0][key]}"></label>`).join('')}<button class="btn secondary small" data-action="studio-reset-items">ترتيب العناصر تلقائيًا</button><h3>مكان المجموعة</h3>${[['stampX','المكان الأفقي',0,100,50],['stampY','المكان الرأسي',0,100,60],['stampSize','حجم العناصر',22,160,38]].map(([key,label,min,max,value])=>`<label class="field"><span>${label}</span><input type="range" data-studio="${key}" aria-label="${label}" min="${min}" max="${max}" value="${draft[key]??value}"></label>`).join('')}<label class="field"><span>طريقة عرض الخلفية</span><select data-studio="backgroundMode"><option value="soft" ${draft.backgroundMode!=='artwork'?'selected':''}>خلفية ناعمة مع طبقات التصميم</option><option value="artwork" ${draft.backgroundMode==='artwork'?'selected':''}>تصميم كامل جاهز · الصورة واضحة</option></select></label><label class="studio-toggle"><input type="checkbox" data-studio="hideIdentity" ${draft.hideIdentity?'checked':''}> الخلفية تحتوي الشعار والاسم — أخفِ الهوية المكررة</label><p class="line-meta">يفضل مقاس ٩٠٠ × ١٦٠٠ بكسل. تبقى الأختام والرمز عناصر حية فوق الصورة.</p></div>`);}return box.innerHTML;};
const studioRefreshMedia=refreshMedia;
refreshMedia=function(){studioRefreshMedia();const el=document.getElementById('media-stampEmptyImage');if(!draft.stampEmptyImage){const input=document.getElementById('stamp-empty-file');if(input){input.value='';input.dataset.generation='removed';}}if(el)el.innerHTML=draft.stampEmptyImage?`<div class="uploaded-image"><img src="${esc(draft.stampEmptyImage)}" alt="قبل الزيارة"><button class="image-remove" data-action="media-remove" data-key="stampEmptyImage" aria-label="إزالة صورة قبل الزيارة">×</button></div>`:'<p class="line-meta">بدون صورة: نستخدم الرسم الجاهز.</p>';};
const studioBindEditor=bindEditor;
bindEditor=function(){studioBindEditor();document.querySelectorAll('[data-studio]').forEach(el=>el.addEventListener('input',()=>{draft.layout??='glass';const key=el.dataset.studio,prior=draft[key]??(key==='stampX'?50:60);if(['stampX','stampY'].includes(key)&&draft.itemCoordinateSpace==='card'&&draft.elementLayout){const axis=key==='stampX'?'x':'y',delta=Number(el.value)-prior;draft.elementLayout=draft.elementLayout.map(pos=>({...pos,[axis]:Math.max(0,Math.min(100,pos[axis]+delta))}));}draft[el.dataset.studio]=el.type==='checkbox'?el.checked:el.type==='range'?Number(el.value):el.value;if(el.dataset.studio==='stampSize'&&draft.elementLayout)draft.elementLayout=draft.elementLayout.map(pos=>({...pos,size:Number(el.value)}));updatePreview();}));const input=document.getElementById('stamp-empty-file');input?.addEventListener('change',async()=>{const f=input.files[0];if(!f)return;if(!['image/png','image/jpeg','image/webp'].includes(f.type)||f.size>5242880){toast('اختر صورة حتى ٥ ميجابايت.');input.value='';return;}const generation=crypto.randomUUID();input.dataset.generation=generation;try{const value=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(f);});const img=new Image();img.src=value;await img.decode();if(!input.isConnected||input.dataset.generation!==generation)return;draft.stampEmptyImage=value;draft.layout??='glass';updatePreview();}catch{toast('الصورة غير قابلة للعرض.');}});};
mutationActions.add('studio-style');
const studioDemoBalances=new Map();
window.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='studio-style'){e.preventDefault();e.stopImmediatePropagation();if(!canOperate())return toast('يلزم تفعيل الاشتراك.');draft.layout=b.dataset.style;render();}else if(b.dataset.action==='studio-demo'){e.preventDefault();e.stopImmediatePropagation();const c=studioTemplates.find(x=>x.id===b.dataset.template);if(!c)return;let m=studioDemoBalances.get(c.id)||{stamps:2,points:20,rewards:0,id:'RJ-PREVIEW01',name:'معاينة'};const p=Loyalty.program(c);if(Loyalty.available(m,c)){m={stamps:0,points:0,rewards:0,id:m.id,name:m.name};}else Loyalty.apply(m,c,'stamp');studioDemoBalances.set(c.id,m);const el=document.getElementById('demo-card-'+c.id);if(el)el.innerHTML=cardHTML(c,m);b.textContent=Loyalty.available(m,c)?'المكافأة جاهزة · أعد التجربة ↗':`جرّب ${p.type==='points'?'إضافة نقاط':'زيارة'} ↗`;}},true);
const studioRender=render;render=function(){studioRender();document.querySelectorAll('.demo-visit').forEach(b=>b.addEventListener('pointerdown',e=>e.stopPropagation()));};
render();

function studioPositions(c){const columns=Math.min(5,c.target),rows=Math.ceil(c.target/columns);return Array.from({length:c.target},(_,i)=>{const pos=c.elementLayout?.[i];return pos&&Number.isFinite(pos.x)&&Number.isFinite(pos.y)&&Number.isFinite(pos.size)?pos:{x:c.itemCoordinateSpace==='card'?(c.stampX??50)+((i%columns+.5)/columns*100-50)*.886:(i%columns+.5)/columns*100,y:c.itemCoordinateSpace==='card'?(c.stampY??60)+((Math.floor(i/columns)+.5)/rows*100-50)*.193:(Math.floor(i/columns)+.5)/rows*100,size:Number(c.stampSize)||38};});}
const freeBindEditor=bindEditor;
bindEditor=function(){freeBindEditor();const selector=document.getElementById('studio-item-select'),preview=document.getElementById('card-preview');if(!selector||!preview)return;if(draft.itemCoordinateSpace!=='card'){const card=preview.querySelector('.studio-card'),bounds=card?.getBoundingClientRect();if(bounds?.width&&bounds.height){draft.elementLayout=Array.from(preview.querySelectorAll('.studio-stamp'),el=>{const b=el.getBoundingClientRect();return {x:Math.max(0,Math.min(100,((b.left+b.width/2)-bounds.left)/bounds.width*100)),y:Math.max(0,Math.min(100,((b.top+b.height/2)-bounds.top)/bounds.height*100)),size:Number(el.style.getPropertyValue('--stamp-size').replace('px',''))||38};});draft.itemCoordinateSpace='card';updatePreview();}}let selected=0;const controls=Array.from(document.querySelectorAll('[data-item-control]'));const sync=()=>{const pos=studioPositions(draft)[selected];selector.value=String(selected);controls.forEach(el=>el.value=pos[el.dataset.itemControl]);preview.querySelectorAll('.studio-stamp').forEach(el=>el.classList.toggle('studio-selected',Number(el.dataset.item)===selected));};selector.addEventListener('change',()=>{selected=Number(selector.value);sync();});controls.forEach(el=>el.addEventListener('input',()=>{draft.elementLayout=studioPositions(draft);draft.elementLayout[selected]={...draft.elementLayout[selected],[el.dataset.itemControl]:Number(el.value)};updatePreview();sync();}));let drag=null;preview.addEventListener('pointerdown',e=>{const item=e.target.closest('.studio-stamp');if(!item||!e.isPrimary)return;e.preventDefault();selected=Number(item.dataset.item);draft.elementLayout=studioPositions(draft);drag={id:e.pointerId,bounds:item.parentElement.getBoundingClientRect()};preview.setPointerCapture(e.pointerId);sync();});preview.addEventListener('pointermove',e=>{if(!drag||drag.id!==e.pointerId)return;const pos=draft.elementLayout[selected];pos.x=Math.max(0,Math.min(100,(e.clientX-drag.bounds.left)/drag.bounds.width*100));pos.y=Math.max(0,Math.min(100,(e.clientY-drag.bounds.top)/drag.bounds.height*100));const el=preview.querySelector(`[data-item="${selected}"]`);if(el){el.style.left=pos.x+'%';el.style.top=pos.y+'%';}controls.forEach(el=>el.value=pos[el.dataset.itemControl]);});const end=()=>{if(!drag)return;drag=null;updatePreview();sync();};preview.addEventListener('pointerup',end);preview.addEventListener('pointercancel',end);sync();};
mutationActions.add('studio-reset-items');window.addEventListener('click',e=>{if(!e.target.closest('[data-action="studio-reset-items"]'))return;e.preventDefault();e.stopImmediatePropagation();if(!canOperate())return toast('يلزم تفعيل الاشتراك.');delete draft.elementLayout;delete draft.itemCoordinateSpace;render();},true);
render();
